template <typename scalar_t>
__global__ __launch_bounds__(512)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    int tid = threadIdx.x;
    int bdim = blockDim.x;

    // Use float4 for vectorized loads
    int vec_hidden = hidden_size / 4;
    const float4* x_vec = reinterpret_cast<const float4*>(x);
    const float4* w_vec = reinterpret_cast<const float4*>(weight);
    float4* o_vec = reinterpret_cast<float4*>(o);

    // Step 1: compute sum of squares using vectorized loads
    float sum_sq = 0.0f;
    for (int i = tid; i < vec_hidden; i += bdim) {
        float4 xv = x_vec[i];
        sum_sq += xv.x * xv.x + xv.y * xv.y + xv.z * xv.z + xv.w * xv.w;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = tid & 31;
    int warp_id = tid >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (bdim + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (tid == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    // Step 2: normalize and scale using vectorized loads/stores
    for (int i = tid; i < vec_hidden; i += bdim) {
        float4 xv = __ldg(&x_vec[i]);
        float4 wv = __ldg(&w_vec[i]);
        float4 ov;
        ov.x = xv.x * rms_inv * wv.x;
        ov.y = xv.y * rms_inv * wv.y;
        ov.z = xv.z * rms_inv * wv.z;
        ov.w = xv.w * rms_inv * wv.w;
        o_vec[i] = ov;
    }
}
```

