Actually wait, let me reconsider. The block size is determined by `min(hidden, 1024)`. For hidden=2048, that's 1024. If I change to 256, I need to change the host wrapper too.

Let me just make the register caching optimization with the existing block size. That's simpler and lower risk.

Here's my plan for RMSNorm:

```cpp
template <typename scalar_t>
__global__ __launch_bounds__(1024)
void rmsnorm_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    scalar_t* __restrict__ output,
    int hidden_size,
    float eps
) {
    int row = blockIdx.x;
    const scalar_t* x = input + row * hidden_size;
    scalar_t* o = output + row * hidden_size;

    // Cache input values in registers to avoid double-loading
    float sum_sq = 0.0f;
    float c0 = 0.0f, c1 = 0.0f;
    int i0 = threadIdx.x;
    int i1 = threadIdx.x + blockDim.x;

    if (i0 < hidden_size) {
        c0 = static_cast<float>(__ldg(&x[i0]));
        sum_sq += c0 * c0;
    }
    if (i1 < hidden_size) {
        c1 = static_cast<float>(__ldg(&x[i1]));
        sum_sq += c1 * c1;
    }

    // Handle additional iterations for large hidden_size
    for (int i = i1 + blockDim.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        sum_sq += val * val;
    }

    // Warp-level reduction
    for (int offset = warpSize / 2; offset > 0; offset >>= 1)
        sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);

    __shared__ float shared[32];
    int lane = threadIdx.x & 31;
    int warp_id = threadIdx.x >> 5;

    if (lane == 0) shared[warp_id] = sum_sq;
    __syncthreads();

    if (warp_id == 0) {
        int num_warps = (blockDim.x + 31) >> 5;
        sum_sq = (lane < num_warps) ? shared[lane] : 0.0f;
        for (int offset = warpSize / 2; offset > 0; offset >>= 1)
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
    }

    __shared__ float s_rms_inv;
    if (threadIdx.x == 0) {
        s_rms_inv = rsqrtf(sum_sq / hidden_size + eps);
    }
    __syncthreads();

    float rms_inv = s_rms_inv;

    // Normalize and scale using cached input values
    if (i0 < hidden_size) {
        float w0 = static_cast<float>(__ldg(&weight[i0]));
        o[i0] = static_cast<scalar_t>(c0 * rms_inv * w0);
    }
    if (i1 < hidden_size) {
        float w1 = static_cast<float>(__ldg(&weight[i1]));
        o[i1] = static_cast<scalar_t>(c1 * rms_inv * w1);
    }

    for (int i = i1 + blockDim.x; i < hidden_size; i += blockDim.x) {
        float val = static_cast<float>(__ldg(&x[i]));
        float w = static_cast<float>(__ldg(&weight[i]));
        o[i] = static_cast<scalar_t>(val * rms_inv * w);
    }
}
```

This is clean and simple. The main change is:
1. Cache the first 2 input values in scalar registers c0, c1
2. Reuse them in the normalization step, avoiding re-reading from global memory
3. Fallback loop for hidden_size > 2*blockDim

